import React from 'react'
import background from '../images/bg.jpg'

function HomeScreen() {
  return (
    <div style={{backgroundImage: `url(${background})`, backgroundRepeat: 'no-repeat', backgroundPosition: 'center', backgroundSize: 'cover', width: '70vw', height: '100vh', borderTopRightRadius: '10%',borderBottomRightRadius: '10%', opacity: 0.3}}>
        <div style={{ backdropFilter: 'blur(5px)', position: 'relative', top: 50, right: 100,fontSize: 60, textAlign: 'right', color: '#0F0404'}}> Connect with Your co-passengers</div>
    </div>
  )
}

export default HomeScreen
